<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Epoch Clock','description'=>'View the current Unix epoch time in seconds and milliseconds.','url'=>'https://smarttoolz.in/tools/epoch-clock/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Epoch Clock</h1><p>Live Unix epoch time.</p></section><section class="tool-workspace"><div class="tool-panel"><div id="o" style="font-size:30px;font-weight:800"></div></div></section></main><script>function go(){let n=Date.now();o.textContent=`Seconds: ${Math.floor(n/1000)} · Milliseconds: ${n}`}setInterval(go,1000);go()</script><?php smarttoolz_tool_page_end(); ?>